def shift_down(g,bg):
    h,w=len(g),len(g[0])
    out=[[bg]*w for _ in range(h)]
    for r in range(h-1):
        for c in range(w):
            if g[r][c]!=bg: out[r+1][c]=g[r][c]
    return out
